def _materialise(name: str, encoded: str) -> Path:
    """Write an embedded asset to a temp file and return its path."""
    target = Path(tempfile.gettempdir()) / "tlo_brand" / name
    target.parent.mkdir(parents=True, exist_ok=True)
    if not target.exists() or target.stat().st_size == 0:
        target.write_bytes(base64.b64decode(encoded))
    return target


def resolve(which: str = "wordmark") -> Path | None:
    """Return a usable path to the wordmark or the square mark.

    Prefers assets/ so the files can be swapped without touching the code, and
    falls back to the embedded copy. Returns None only if both routes fail.
    """
    filename, encoded = {
        "wordmark": ("tlo_logo.png", WORDMARK_B64),
        "wordmark_dark": ("tlo_logo_dark.png", WORDMARK_DARK_B64),
        "mark": ("tlo_mark.png", MARK_B64),
    }[which]

    on_disk = ASSETS / filename
    try:
        if on_disk.exists() and on_disk.stat().st_size > 0:
            return on_disk
    except OSError:
        pass

    try:
        return _materialise(filename, encoded)
    except Exception:          # noqa: BLE001 - branding must never break the app
        return None


def source(which: str = "wordmark") -> str:
    """Say where the asset came from, for the diagnostics in the sidebar."""
    filename = {"wordmark": "tlo_logo.png", "wordmark_dark": "tlo_logo_dark.png", "mark": "tlo_mark.png"}[which]
    path = resolve(which)
    if path is None:
        return "unavailable"
    return "assets folder" if path == ASSETS / filename else "embedded copy"
